def _append_only() -> None:
    op.execute(
        """
        CREATE FUNCTION ledger.forbid_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
          RAISE EXCEPTION 'qp: %.% is append-only (% rejected); correct with a reversal',
            TG_TABLE_SCHEMA, TG_TABLE_NAME, TG_OP USING ERRCODE = 'restrict_violation';
        END $$;
        """
    )
    op.execute(
        """
        CREATE FUNCTION ledger.stamp_recorded_at() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
          NEW.recorded_at := now();  -- entries cannot be backdated
          RETURN NEW;
        END $$;
        """
    )
    for table in APPEND_ONLY:
        op.execute(
            f"CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON {table} "
            "FOR EACH ROW EXECUTE FUNCTION ledger.forbid_mutation()"
        )
        op.execute(
            f"CREATE TRIGGER append_only_truncate BEFORE TRUNCATE ON {table} "
            "FOR EACH STATEMENT EXECUTE FUNCTION ledger.forbid_mutation()"
        )
    for table in STAMPED:
        op.execute(
            f"CREATE TRIGGER stamp_recorded_at BEFORE INSERT ON {table} "
            "FOR EACH ROW EXECUTE FUNCTION ledger.stamp_recorded_at()"
        )


